-- Patch for already-seeded environments only.
--
-- Syncs the Vital Event Details section's section_ui_schema to the canonical
-- definition in g2p_register_sections.sql (line
-- 'livestock_vital_event_details_section_01'). The seed only INSERTs and never
-- touches an existing row, so environments seeded before that line changed
-- keep the old dialog forever; this re-applies the whole schema by section_id.
--
-- Why: the official staff-ui cannot fill a dialog column from another
-- section's rows ("sibling-table" source) nor cascade one dialog column from
-- another, so the Ear Tag picker rendered EMPTY (and, on Vaccination, the
-- Vaccine list too). Ear Tag is now a text input (server-checked against this
-- submission's animals), Vaccine the plain VACCINE_TYPE list (server-checked
-- against the animal's species), Species is filled by the server from the
-- animal, and dialog conditions use operators the official UI supports.
-- Also: Notifiable Disease / Pregnancy Confirmed are required only while
-- their show-condition holds (conditional "require" action, like
-- disease_type) — a hidden-but-required radio blocked every non-DISEASE
-- event on Next ("Row 1, Notifiable Disease: This field is required").
--
-- 2026-09-22: Event Date is hidden until an Event Type is picked (show +
-- require both on "event_type notEmpty", the one-condition style forced by
-- the dialog-table condition engine — see patch_ls_health_event_details_
-- sync_ui_schema.sql's note on bt()/br() taking only the LAST action, not an
-- AND of several) and defaults to today (widget-data-default; resolved
-- server-side by G2PRegisterDomainServiceVitalEvent.validate_domain_attributes
-- — resolve_today_default, same as Animal/Farmer registration_date).
-- New Ear Tag Prefix (offspring_ear_tag_prefix) is dropped — it was never
-- read anywhere server-side, a dead field from the start. New Ear Tag(s)
-- (offspring_ear_tags, read-only) is dropped too; the tags are still reserved
-- and end up on the created offspring's own Animal row under Livestock
-- Details — staff just no longer see them echoed back on this row.
-- Sex of Offspring gains Mixed / Not Applicable (GenderEnum.MIXED) — one
-- offspring_gender value covers the whole litter/count on a Birth event, and
-- a litter of both sexes couldn't honestly pick Male or Female before.
-- Generated from the seed line; keep the two in sync.
UPDATE "public"."g2p_register_sections"
SET section_ui_schema = '{"panels": [{"panels": [{"widgets": [{"widget": "dialog-table", "widget-id": "ls_vital_event_details_table", "widget-type": "dialog-table", "widget-label": "Vital Event Details", "widget-readonly": false, "widget-data-path": "76811bf6-07df-5ed4-9466-13b782f627fe.records", "widget-data-columns": [{"widget": "text", "column-key": "ear_tag_id", "widget-type": "input", "widget-label": "Ear Tag / Secondary Identifier", "widget-autofill": {"fields": {"age": "age", "species": "species"}, "matchField": "ear_tag_id", "sourceWidgetId": "ls_animal_details_table"}, "widget-readonly": false, "widget-required": false, "widget-data-path": "ear_tag_id", "widget-placeholder": "ET + 10 digits, e.g. ET0000000123", "widget-data-options": {"actions": [{"action": "require", "condition": {"field": "ear_tag_id", "operator": "empty"}}]}}, {"widget": "select", "column-key": "species", "widget-type": "input", "widget-label": "Species", "widget-readonly": true, "widget-data-path": "species", "widget-data-source": {"type": "api", "method": "POST", "params": {"page_size": 500, "attribute_id": "LIVESTOCK_TYPE"}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}}, {"widget": "text", "column-key": "age", "widget-type": "input", "widget-label": "Age", "widget-readonly": true, "widget-data-path": "age"}, {"widget": "select", "column-key": "event_type", "widget-type": "input", "widget-label": "Event Type", "widget-readonly": false, "widget-required": false, "widget-data-path": "event_type", "widget-data-source": {"type": "static", "options": [{"label": "BIRTH", "value": "BIRTH"}, {"label": "MORTALITY", "value": "MORTALITY"}, {"label": "DISEASE", "value": "DISEASE"}]}, "widget-data-options": {"actions": [{"action": "require", "condition": {"field": "event_type", "operator": "empty"}}]}}, {"widget": "date", "column-key": "event_date", "widget-type": "input", "widget-label": "Event Date", "widget-readonly": false, "widget-data-path": "event_date", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker", "dateConstraint": "any"}, "widget-data-placeholder": "dd_mm_yyyy", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}, {"action": "require", "condition": {"field": "event_type", "operator": "notEmpty"}}]}, "widget-data-default": "today"}, {"widget": "select", "column-key": "cause", "widget-type": "input", "widget-label": "Cause", "widget-readonly": false, "widget-data-path": "cause", "widget-data-source": {"type": "static", "options": [{"label": "DISEASE", "value": "DISEASE"}, {"label": "ACCIDENT", "value": "ACCIDENT"}, {"label": "PREDATION", "value": "PREDATION"}, {"label": "SLAUGHTER", "value": "SLAUGHTER"}, {"label": "UNKNOWN", "value": "UNKNOWN"}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "MORTALITY", "operator": "equals"}}]}}, {"widget": "select", "column-key": "location", "widget-type": "input", "widget-label": "Location", "widget-readonly": false, "widget-data-path": "location", "widget-data-source": {"type": "static", "options": [{"label": "HOME", "value": "HOME"}, {"label": "VETERINARY", "value": "VETERINARY"}, {"label": "MARKET", "value": "MARKET"}, {"label": "FIELD", "value": "FIELD"}, {"label": "QUARANTINE_CENTER", "value": "QUARANTINE_CENTER"}, {"label": "OTHER", "value": "OTHER"}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "text", "column-key": "location_details", "widget-type": "input", "widget-label": "Location Details", "widget-readonly": false, "widget-data-path": "location_details", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "select", "column-key": "disease_type", "widget-type": "input", "widget-label": "Disease / Diagnosis", "widget-readonly": false, "widget-data-path": "disease_type", "widget-data-source": {"type": "api", "method": "POST", "params": {"page_size": 500, "attribute_id": "LIVESTOCK_DISEASE"}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}, {"action": "require", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}]}}, {"widget": "date", "column-key": "date_onset", "widget-type": "input", "widget-label": "Date of Onset", "widget-readonly": false, "widget-data-path": "date_onset", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker"}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}]}, "widget-data-placeholder": "dd_mm_yyyy"}, {"widget": "date", "column-key": "date_resolution", "widget-type": "input", "widget-label": "Date of Resolution", "widget-readonly": false, "widget-data-path": "date_resolution", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker"}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}]}, "widget-data-validation": {"notBeforeField": "date_onset", "notBeforeFieldMessage": "Date of Resolution cannot be before Date of Onset"}, "widget-data-placeholder": "dd_mm_yyyy"}, {"widget": "text", "column-key": "treatment", "widget-type": "input", "widget-label": "Treatment Administered", "widget-readonly": false, "widget-data-path": "treatment", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}]}}, {"widget": "text", "column-key": "veterinarian_name", "widget-type": "input", "widget-label": "Attending Veterinarian", "widget-readonly": false, "widget-data-path": "veterinarian_name", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}]}}, {"widget": "radio", "column-key": "is_notifiable", "widget-type": "input", "widget-label": "Notifiable Disease", "widget-readonly": false, "widget-data-path": "is_notifiable", "widget-data-source": {"type": "static", "options": [{"label": "YES", "value": true}, {"label": "NO", "value": false}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}, {"action": "require", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}]}}, {"widget": "number", "column-key": "offspring_count", "widget-type": "input", "widget-label": "Number of Offspring", "widget-readonly": false, "widget-data-path": "offspring_count", "widget-data-format": {"textAlign": "right", "numericType": "integer", "thousandSeparator": ","}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "BIRTH", "operator": "equals"}}, {"action": "require", "condition": {"field": "event_type", "value": "BIRTH", "operator": "equals"}}]}}, {"widget": "select", "column-key": "offspring_gender", "widget-type": "input", "widget-label": "Sex of Offspring", "widget-readonly": false, "widget-data-path": "offspring_gender", "widget-data-source": {"type": "static", "options": [{"label": "MALE", "value": "MALE"}, {"label": "FEMALE", "value": "FEMALE"}, {"label": "Mixed / Not Applicable", "value": "MIXED"}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "BIRTH", "operator": "equals"}}, {"action": "require", "condition": {"field": "event_type", "value": "BIRTH", "operator": "equals"}}]}}, {"widget": "text", "column-key": "reporting_officer", "widget-type": "input", "widget-label": "Reporting Officer", "widget-readonly": false, "widget-data-path": "reporting_officer", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "text", "column-key": "notes", "widget-type": "input", "widget-label": "Notes", "widget-readonly": false, "widget-data-path": "notes", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}], "widget-data-operations": {"add": true, "edit": true, "remove": true}, "widget-data-dialog-title-add": "Add Vital Event Details", "widget-data-dialog-title-edit": "Edit Vital Event Details"}], "panel-id": "vertical_panel_ls_vital_event_details_1", "panel-orientation": "vertical"}], "panel-id": "horizontal_panel_ls_vital_event_details", "panel-orientation": "horizontal"}], "section-id": "livestock_vital_event_details_section_01", "section-title": "Vital Event Details", "section-editable": true, "section-required-for-submit": false}'::jsonb
WHERE section_id = 'livestock_vital_event_details_section_01';
